<?php
require_once __DIR__ . '/config.php'; require_login();
$pdo = db(); $user = current_user(); $allStages = stages();
$flash = $_SESSION['flash'] ?? null; unset($_SESSION['flash']);
$where = ''; $params = [];
if (!is_admin()) { $where = ' WHERE u.stage = ?'; $params[] = $user['assigned_stage']; }
$sql = "SELECT j.*, u.stage, u.status, u.completed_quantity, u.note AS stage_note, u.updated_at AS stage_updated,
        emp.full_name AS updated_by
        FROM production_jobs j
        JOIN production_updates u ON u.job_id=j.id
        LEFT JOIN users emp ON emp.id=u.employee_id";
if (!is_admin()) $sql .= " WHERE u.stage = ?";
$sql .= " ORDER BY CASE u.status WHEN 'in_progress' THEN 0 WHEN 'pending' THEN 1 ELSE 2 END, j.due_date IS NULL, j.due_date ASC, j.created_at DESC";
$stmt = $pdo->prepare($sql); $stmt->execute($params); $rows = $stmt->fetchAll();
$jobs = $pdo->query("SELECT COUNT(*) FROM production_jobs")->fetchColumn();
$completed = $pdo->query("SELECT COUNT(*) FROM production_updates WHERE status='completed'")->fetchColumn();
$inProgress = $pdo->query("SELECT COUNT(*) FROM production_updates WHERE status='in_progress'")->fetchColumn();
$pending = $pdo->query("SELECT COUNT(*) FROM production_updates WHERE status='pending'")->fetchColumn();
$recent = $pdo->query("SELECT h.*, j.job_code, j.book_title, u.full_name AS changed_by_name FROM production_history h JOIN production_jobs j ON j.id=h.job_id LEFT JOIN users u ON u.id=h.changed_by ORDER BY h.changed_at DESC LIMIT 8")->fetchAll();
function progress_for_job(PDO $pdo, int $jobId): array {
    $s=$pdo->prepare("SELECT stage,status,completed_quantity FROM production_updates WHERE job_id=?"); $s->execute([$jobId]); $out=[];
    foreach($s->fetchAll() as $r) $out[$r['stage']]=$r; return $out;
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard | <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><div class="brand-mark">BP</div><div><strong>BOOKPRINTERS</strong><small>& SHREEPUBLICATIONS</small></div></a><div class="side-label">WORKSPACE</div><a class="nav-link active" href="dashboard.php"><span>▦</span> Overview</a><?php if(is_admin()): ?><a class="nav-link" href="jobs.php"><span>▤</span> Production jobs</a><a class="nav-link" href="employees.php"><span>♙</span> Employees & access</a><?php endif; ?><div class="sidebar-bottom"><div class="user-mini"><div class="avatar"><?=e(strtoupper(substr($user['full_name'],0,1)))?></div><div><strong><?=e($user['full_name'])?></strong><small><?=is_admin()?'Administrator':e($allStages[$user['assigned_stage']]['label'] ?? 'Employee')?></small></div></div><a class="nav-link logout" href="logout.php"><span>↪</span> Sign out</a></div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">PRODUCTION MANAGEMENT</p><h1>Overview</h1></div><div class="top-actions"><span class="live-dot"></span><span class="small muted">Live production records</span><div class="avatar"><?=e(strtoupper(substr($user['full_name'],0,1)))?></div></div></header><section class="welcome-row"><div><h2><?=is_admin()?'Good to see you, '.e($user['full_name']).' 👋':'Your production work, at a glance'?></h2><p class="muted"><?=is_admin()?'Here is what is happening across your book production line.':'Update the stage assigned to you as work progresses.'?></p></div><?php if(is_admin()): ?><a class="btn primary" href="jobs.php?action=new">＋ Create production job</a><?php endif; ?></section>
<?php if($flash): ?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif; ?>
<section class="stats-grid"><?php if(is_admin()): ?><article class="stat-card"><div class="stat-top"><span>Total book jobs</span><span class="stat-icon blue">▤</span></div><strong><?=number_format((int)$jobs)?></strong><small>Production orders created</small></article><?php endif; ?><article class="stat-card"><div class="stat-top"><span><?=is_admin()?'Stages completed':'My stages completed'?></span><span class="stat-icon green">✓</span></div><strong><?=number_format((int)(is_admin()?$completed:count(array_filter($rows,fn($r)=>$r['status']==='completed'))))?></strong><small>Marked as completed</small></article><article class="stat-card"><div class="stat-top"><span>In progress</span><span class="stat-icon amber">◷</span></div><strong><?=number_format((int)(is_admin()?$inProgress:count(array_filter($rows,fn($r)=>$r['status']==='in_progress'))))?></strong><small>Work currently underway</small></article><article class="stat-card"><div class="stat-top"><span>Pending</span><span class="stat-icon rose">!</span></div><strong><?=number_format((int)(is_admin()?$pending:count(array_filter($rows,fn($r)=>$r['status']==='pending'))))?></strong><small>Waiting to be started</small></article></section>
<section class="panel"><div class="panel-heading"><div><h3><?=is_admin()?'Production pipeline':'My assigned work'?></h3><p class="muted small"><?=is_admin()?'Track each book through all five stages.':'Only jobs for your assigned production stage are shown.'?></p></div><div class="search-wrap"><span>⌕</span><input id="jobSearch" placeholder="Search book or job code..."></div></div><div class="table-wrap"><table id="jobsTable"><thead><tr><th>Book / Job ID</th><?php if(is_admin()): ?><th>Production progress</th><?php endif; ?><th>Quantity</th><th>Due date</th><th>Stage status</th><th>Last update</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): $prog=progress_for_job($pdo,(int)$r['id']); $done=count(array_filter($prog,fn($x)=>$x['status']==='completed')); $percent=(int)round($done/5*100); ?><tr><td><div class="book-cell"><div class="book-icon">▤</div><div><strong><?=e($r['book_title'])?></strong><small><?=e($r['job_code'])?><?= $r['client_name']?' · '.e($r['client_name']):'' ?></small></div></div></td><?php if(is_admin()): ?><td><div class="progress-meta"><span><?=$done?> of 5 stages</span><strong><?=$percent?>%</strong></div><div class="progress-track"><span style="width:<?=$percent?>%"></span></div><div class="mini-stages"><?php foreach($allStages as $key=>$stage): ?><span title="<?=e($stage['label'])?>" class="<?=e($prog[$key]['status']??'pending')?>"></span><?php endforeach; ?></div></td><?php endif; ?><td><strong><?=number_format((int)$r['total_quantity'])?></strong><small class="subline">copies</small></td><td><?=e($r['due_date'] ?: '—')?></td><td><span class="status <?=e($r['status'])?>"><?=e(stage_status_label($r['status']))?></span><small class="subline"><?=e($allStages[$r['stage']]['label']??$r['stage'])?></small></td><td><?=e($r['stage_updated'] ? date('d M, g:i A',strtotime($r['stage_updated'])) : 'Not updated')?><small class="subline"><?=e($r['updated_by']??'No update yet')?></small></td><td><a class="btn small-btn <?=is_admin()?'secondary':'primary'?>" href="update.php?job_id=<?=(int)$r['id']?>&stage=<?=e($r['stage'])?>"><?=is_admin()?'View / update':'Update work'?> →</a></td></tr><?php endforeach; ?></tbody></table><?php if(!$rows): ?><div class="empty-state"><div>▤</div><h3>No production work yet</h3><p>When a production job is created, it will appear here.</p><?php if(is_admin()): ?><a class="btn primary" href="jobs.php?action=new">Create first job</a><?php endif; ?></div><?php endif; ?></div></section>
<?php if(is_admin()): ?><section class="panel history-panel"><div class="panel-heading"><div><h3>Recent activity</h3><p class="muted small">Latest production updates across the factory</p></div><span class="muted small">Latest 8 updates</span></div><?php if($recent): ?><div class="activity-list"><?php foreach($recent as $h): ?><div class="activity-item"><div class="activity-dot"></div><div class="activity-content"><strong><?=e($h['book_title'])?></strong><span><?=e($allStages[$h['stage']]['label'])?> marked <b><?=e(stage_status_label($h['status']))?></b> · <?=number_format((int)$h['completed_quantity'])?> copies</span><?php if($h['note']): ?><small><?=e($h['note'])?></small><?php endif; ?></div><time><?=e(date('d M, g:i A',strtotime($h['changed_at'])))?></time></div><?php endforeach; ?></div><?php else: ?><p class="muted empty-line">Activity will appear here as employees update jobs.</p><?php endif; ?></section><?php endif; ?><footer class="footer">© <?=date('Y')?> BookPrinters & ShreePublications <span>Production made visible.</span></footer></main></div></body></html>
